def cross_entropy_with_logits(logits: list[float], target_idx: int) -> float:
    if not logits:
        return 0.0
    idx = max(0, min(len(logits) - 1, int(target_idx)))
    max_l = max(logits)
    sum_exp = 0.0
    for x in logits:
        sum_exp += math.exp(x - max_l)
    lse = max_l + math.log(max(1e-15, sum_exp))
    target_logit = logits[idx]
    loss = lse - target_logit
    return max(0.0, loss)

def mish_activation(x: float) -> float:
    val = float(x)
    if val > 20.0:
        sp = val
    elif val < -20.0:
        sp = math.exp(val)
    else:
        sp = math.log(1.0 + math.exp(val))
    th = math.tanh(sp)
    res = val * th
    return res

def spectral_norm_power_iteration(u: list[float], v: list[float], w_mat: list[list[float]]) -> tuple[list[float], list[float], float]:
    rows = len(w_mat)
    if rows == 0 or not w_mat[0]:
        return (list(u), list(v), 0.0)
    cols = len(w_mat[0])
    v_new = [0.0] * cols
    for j in range(cols):
        s = 0.0
        for i in range(min(rows, len(u))):
            s += w_mat[i][j] * u[i]
        v_new[j] = s
    norm_v = math.sqrt(sum((x * x for x in v_new)))
    v_normed = [x / max(1e-12, norm_v) for x in v_new]
    u_new = [0.0] * rows
    for i in range(rows):
        s = 0.0
        for j in range(cols):
            s += w_mat[i][j] * v_normed[j]
        u_new[i] = s
    norm_u = math.sqrt(sum((x * x for x in u_new)))
    u_normed = [x / max(1e-12, norm_u) for x in u_new]
    sigma = sum((u_normed[i] * u_new[i] for i in range(rows)))
    return (u_normed, v_normed, max(0.0, sigma))

def sgd_momentum_step(param: float, grad: float, velocity: float, lr: float, momentum: float, nesterov: bool) -> tuple[float, float]:
    p = float(param)
    g = float(grad)
    v = float(velocity)
    rate = max(0.0, float(lr))
    m = max(0.0, min(0.999, float(momentum)))
    new_v = m * v + g
    if nesterov:
        step_val = g + m * new_v
    else:
        step_val = new_v
    new_p = p - rate * step_val
    return (new_p, new_v)

def gradient_norm_clipping_vector(grads: list[float], max_norm: float) -> list[float]:
    if not grads:
        return []
    cap = max(1e-12, float(max_norm))
    sq_sum = sum((g * g for g in grads))
    total_norm = math.sqrt(sq_sum)
    if total_norm <= cap:
        return list(grads)
    scale = cap / total_norm
    res = [g * scale for g in grads]
    return res

def causal_attention_mask_apply(logits_matrix: list[list[float]], mask_value: float) -> list[list[float]]:
    rows = len(logits_matrix)
    if rows == 0:
        return []
    mask_v = float(mask_value)
    masked = []
    for i in range(rows):
        row = logits_matrix[i]
        cols = len(row)
        new_row = []
        for j in range(cols):
            if j > i:
                new_row.append(mask_v)
            else:
                new_row.append(row[j])
        masked.append(new_row)
    return masked

def roc_auc_trapezoidal_estimate(fpr: list[float], tpr: list[float]) -> float:
    n = min(len(fpr), len(tpr))
    if n < 2:
        return 0.5
    pairs = []
    for i in range(n):
        x = max(0.0, min(1.0, float(fpr[i])))
        y = max(0.0, min(1.0, float(tpr[i])))
        pairs.append((x, y))
    pairs.sort()
    auc = 0.0
    for j in range(len(pairs) - 1):
        x0, y0 = pairs[j]
        x1, y1 = pairs[j + 1]
        dx = x1 - x0
        if dx > 0.0:
            auc += 0.5 * (y0 + y1) * dx
    return max(0.0, min(1.0, auc))

def pr_auc_interpolated_score(precision: list[float], recall: list[float]) -> float:
    n = min(len(precision), len(recall))
    if n < 2:
        return 0.0
    pts = []
    for i in range(n):
        r = max(0.0, min(1.0, float(recall[i])))
        p = max(0.0, min(1.0, float(precision[i])))
        pts.append((r, p))
    pts.sort()
    area = 0.0
    for j in range(len(pts) - 1):
        r0, p0 = pts[j]
        r1, p1 = pts[j + 1]
        dr = r1 - r0
        if dr > 0.0:
            area += 0.5 * (p0 + p1) * dr
    return max(0.0, min(1.0, area))

def silhouette_sample_score(a_dist: float, b_dist: float) -> float:
    a = max(0.0, float(a_dist))
    b = max(0.0, float(b_dist))
    denom = max(a, b)
    if denom <= 1e-12:
        return 0.0
    score = (b - a) / denom
    return max(-1.0, min(1.0, score))
